fungsi lacak_paket(status) {
    kembalikan cocokkan status {
        StatusPengiriman::Diproses => "📦 Paket sedang disiapkan di gudang.",
        StatusPengiriman::Dikirim(kurir, resi) => "🚚 Dalam perjalanan via " + kurir + " [Resi: " + resi + "]",
        StatusPengiriman::Terkirim => "✅ Paket telah sampai ke penerima.",
        StatusPengiriman::Gagal(alasan) => "❌ Pengiriman gagal: " + alasan,
        _ => "Status tidak dikenali."
    };
}

