// -----------------------------------------------------------------
cetak("4. If Let (jika misal):");
jika misal StatusPengiriman::Dikirim(kurir, resi) = p2 {
    cetak("   ✨ [if let sukses] Ditemukan pengiriman via", kurir, "dengan nomor resi:", resi);
} lainnya {
