    misal px = titik[0]
    misal py = titik[1]
    misal inside = salah
    misal n = panjang(poly)
    misal j = n - 1
    untuk i dalam 0..(n - 1) {
        misal xi = poly[i][0]
        misal yi = poly[i][1]
        misal xj = poly[j][0]
        misal yj = poly[j][1]
        misal cond1 = yi > py
        misal cond2 = yj > py
        misal intersect_cond1 = cond1 != cond2
        misal denom = yj - yi
        misal px_intersect = px
        jika denom != 0 {
            px_intersect = (xj - xi) * (py - yi) / denom + xi
        }
        misal intersect = intersect_cond1 dan (px < px_intersect)
        jika intersect {
            inside = !inside
        }
        j = i
    }
    kembalikan inside
}

