    bytes,
    format_target, // "PE" untuk Windows, "ELF" untuk Linux

    fungsi inisialisasi(format) {
        ini.format_target = format;
        ini.bytes = [];
    }

    fungsi tulis_u8(b) {
        tambah(ini.bytes, b);
    }

    fungsi tulis_u16_le(v) {
        tambah(ini.bytes, v % 256);
        tambah(ini.bytes, (lantai(v / 256)) % 256);
    }

    fungsi tulis_u32_le(v) {
        tambah(ini.bytes, v % 256);
        tambah(ini.bytes, (lantai(v / 256)) % 256);
        tambah(ini.bytes, (lantai(v / 65536)) % 256);
        tambah(ini.bytes, (lantai(v / 16777216)) % 256);
    }

    fungsi tulis_u64_le(v) {
        ini.tulis_u32_le(v);
        ini.tulis_u32_le(0);
    }

    fungsi tulis_string_ascii(teks) {
        misal p = panjang(teks);
        untuk i dalam 0..(p - 1) {
            // Mengambil representasi karakter
            misal ch = teks[i];
            // Konversi karakter umum ASCII
            misal ascii = ini.char_to_ascii(ch);
            ini.tulis_u8(ascii);
        }
    }

    fungsi char_to_ascii(c) {
        misal chars = " !\"#$%&'()*+,-./0123456789:;<=>?@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_`abcdefghijklmnopqrstuvwxyz{|}~";
        misal p = panjang(chars);
        untuk i dalam 0..(p - 1) {
            jika chars[i] == c {
                kembalikan 32 + i;
            }
        }
        jika c == "\n" { kembalikan 10; }
        jika c == "\r" { kembalikan 13; }
        jika c == "\t" { kembalikan 9; }

